/* WordPress Studio sandbox workflow.
 * The "Live Website" partition is a dashboard-only published test version.
 * No production storefront, APIs, database, checkout, or deployment is accessed.
 */
(() => {
  "use strict";
  const REVIEW_KEY = "wp-builder-review-package-v1";
  const PUBLISHED_KEY = "wp-builder-sandbox-published-v1";
  const HISTORY_KEY = "wp-builder-sandbox-history-v1";
  const $ = (id) => document.getElementById(id);
  const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const validNode = (n, depth = 0) => Boolean(n && typeof n === "object" && !Array.isArray(n) && typeof n.id === "string" && ["section","container","heading","paragraph","image","button"].includes(n.type) && n.props && typeof n.props === "object" && Array.isArray(n.children) && depth <= 12 && n.children.length <= 200 && n.children.every((child) => validNode(child, depth + 1)));
  const validDoc = (doc) => Boolean(doc && doc.schemaVersion === 1 && doc.page && typeof doc.page.title === "string" && Array.isArray(doc.tree) && doc.tree.length <= 200 && doc.tree.every((node) => validNode(node)));
  const safeColor = (value) => /^#[0-9a-f]{6}$/i.test(String(value || "")) ? value : "";
  const cssFor = (p) => {
    let css = "";
    if (safeColor(p.background)) css += "background:" + p.background + ";";
    if (safeColor(p.color)) css += "color:" + p.color + ";";
    if (Number.isFinite(Number(p.padding))) css += "padding:" + Math.max(0, Math.min(160, Number(p.padding))) + "px;";
    if (Number.isFinite(Number(p.fontSize))) css += "font-size:" + Math.max(8, Math.min(96, Number(p.fontSize))) + "px;";
    if (["left","center","right"].includes(p.align)) css += "text-align:" + p.align + ";";
    if (/^\d{1,4}(px|%)$/.test(String(p.width || ""))) css += "width:" + p.width + ";";
    if (Number.isFinite(Number(p.height))) css += "height:" + Math.max(40, Math.min(900, Number(p.height))) + "px;";
    return css;
  };
  const renderNode = (node) => {
    const p = node.props || {};
    const children = (node.children || []).map(renderNode).join("");
    const css = cssFor(p);
    if (node.type === "section") return '<section style="' + css + ';box-sizing:border-box;min-height:110px">' + children + "</section>";
    if (node.type === "container") return '<div style="' + css + ';box-sizing:border-box;max-width:1100px;margin-inline:auto">' + children + "</div>";
    if (node.type === "heading") return '<h2 style="' + css + ';font-weight:800;line-height:1.12">' + esc(node.text) + "</h2>";
    if (node.type === "paragraph") return '<p style="' + css + ';line-height:1.65">' + esc(node.text) + "</p>";
    if (node.type === "button") return '<span style="' + css + ';display:inline-block;border-radius:8px;background:' + (safeColor(p.background) || "#35486d") + ';color:' + (safeColor(p.color) || "#fff") + '">' + esc(node.text) + "</span>";
    if (node.type === "image") {
      let src = "";
      try { const url = new URL(p.src || ""); if (["https:","http:"].includes(url.protocol)) src = url.href; } catch (_) {}
      return src ? '<img src="' + esc(src) + '" alt="' + esc(p.alt || "") + '" referrerpolicy="no-referrer" loading="lazy" style="display:block;max-width:100%;object-fit:' + (["cover","contain","fill"].includes(p.fit) ? p.fit : "cover") + ";" + css + '">' : '<div style="padding:24px;background:#eef1f5;color:#68758a">Image placeholder</div>';
    }
    return "";
  };
  const renderDocument = (doc) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><style>*{box-sizing:border-box}body{margin:0;padding:24px;color:#263247;font-family:Inter,system-ui,sans-serif}img{max-width:100%}</style></head><body>' + doc.tree.map(renderNode).join("") + "</body></html>";
  const readJson = (key, fallback = null) => { try { return JSON.parse(localStorage.getItem(key) || "null") ?? fallback; } catch (_) { return fallback; } };
  const writeJson = (key, value) => localStorage.setItem(key, JSON.stringify(value));
  const init = () => {
    const frame = $("wpSandboxFrame");
    if (!frame) return;
    const reviewPanel = $("wpSandboxReview");
    const reviewFrame = $("wpSandboxReviewFrame");
    const empty = $("wpSandboxEmpty");
    const status = $("wpSandboxStatus");
    const publishedMeta = $("wpSandboxPublishedMeta");
    const historyList = $("wpSandboxHistory");
    const viewButtons = [...document.querySelectorAll("[data-sandbox-view]")];
    const stage = $("wpSandboxStage");
    const device = $("wpSandboxDevice");
    let review = readJson(REVIEW_KEY);
    let published = readJson(PUBLISHED_KEY);
    let currentView = "desktop";
    const setStatus = (message) => { if (status) status.textContent = message; };
    const setView = (view) => {
      currentView = view;
      const mobile = view === "mobile";
      if (device) device.classList.toggle("is-mobile", mobile);
      if (stage) stage.classList.toggle("is-mobile-mode", mobile);
      viewButtons.forEach((button) => {
        const active = button.dataset.sandboxView === view;
        button.classList.toggle("is-active", active);
        button.setAttribute("aria-pressed", String(active));
      });
    };
    const loadPublished = () => {
      published = readJson(PUBLISHED_KEY);
      if (!published || !validDoc(published.document)) {
        frame.removeAttribute("srcdoc");
        frame.hidden = true;
        if (empty) empty.hidden = false;
        if (publishedMeta) publishedMeta.textContent = "No Test Published Version yet. Edit a page and publish a test version to see it here.";
        setStatus("Sandbox ready · no test version published");
        return;
      }
      frame.hidden = false;
      if (empty) empty.hidden = true;
      frame.srcdoc = renderDocument(published.document);
      if (publishedMeta) publishedMeta.textContent = "Test Version " + published.version + " · Published " + new Date(published.publishedAt).toLocaleString() + " · " + (published.document.page.title || "Untitled page");
      setStatus("Test Version " + published.version + " loaded · sandbox only");
      renderHistory();
    };
    const renderHistory = () => {
      if (!historyList) return;
      const history = readJson(HISTORY_KEY, []);
      historyList.replaceChildren();
      if (!Array.isArray(history) || !history.length) {
        const item = document.createElement("li");
        item.textContent = "No test versions yet.";
        historyList.append(item);
        return;
      }
      history.slice(0, 12).forEach((entry) => {
        const item = document.createElement("li");
        const title = document.createElement("strong");
        title.textContent = "Version " + entry.version + " · " + (entry.title || "Untitled page");
        const meta = document.createElement("small");
        meta.textContent = new Date(entry.publishedAt).toLocaleString();
        item.append(title, meta);
        historyList.append(item);
      });
    };
    const renderReview = () => {
      review = readJson(REVIEW_KEY);
      if (!reviewPanel) return;
      const valid = review && validDoc(review.document) && ["in_review","approved","rejected","test_published"].includes(review.status);
      reviewPanel.hidden = !valid;
      if (!valid) return;
      $("wpSandboxReviewTitle").textContent = review.document.page.title || "Submitted draft";
      $("wpSandboxReviewMeta").textContent = "Submitted " + new Date(review.sentAt).toLocaleString() + " · Review ID " + review.reviewId;
      $("wpSandboxReviewState").textContent = review.status.replaceAll("_"," ").toUpperCase();
      $("wpSandboxReviewState").dataset.state = review.status;
      $("wpSandboxApprove").disabled = review.status !== "in_review";
      $("wpSandboxPublish").disabled = review.status !== "approved";
      $("wpSandboxPublish").textContent = review.status === "test_published" ? "Test version published" : "Publish Test Version";
      if (review.status === "in_review" || review.status === "approved") {
        reviewFrame.hidden = false;
        reviewFrame.srcdoc = renderDocument(review.document);
      } else {
        reviewFrame.hidden = true;
        reviewFrame.removeAttribute("srcdoc");
      }
    };
    const approve = () => {
      review = readJson(REVIEW_KEY);
      if (!review || !validDoc(review.document) || review.status !== "in_review") return;
      if (!window.confirm("Approve this draft for Test Publish? This only changes the dashboard sandbox.")) return;
      review.status = "approved";
      review.approvedAt = new Date().toISOString();
      writeJson(REVIEW_KEY, review);
      renderReview();
      setStatus("Draft approved · ready for Test Publish");
    };
    const publishTest = () => {
      review = readJson(REVIEW_KEY);
      if (!review || !validDoc(review.document) || review.status !== "approved") return;
      if (!window.confirm("Publish this as a Test Version inside this admin dashboard only? The real WordPress website will not change.")) return;
      published = readJson(PUBLISHED_KEY);
      const history = readJson(HISTORY_KEY, []);
      const version = (Number(published?.version) || 0) + 1;
      const record = { schemaVersion: 1, version, versionId: "sandbox-v" + version + "-" + Date.now(), publishedAt: new Date().toISOString(), sourceReviewId: review.reviewId, document: review.document };
      const before = { published: localStorage.getItem(PUBLISHED_KEY), history: localStorage.getItem(HISTORY_KEY), review: localStorage.getItem(REVIEW_KEY) };
      try {
        writeJson(PUBLISHED_KEY, record);
        writeJson(HISTORY_KEY, [record, ...(Array.isArray(history) ? history : [])].slice(0, 20));
        review.status = "test_published";
        review.testPublishedAt = record.publishedAt;
        review.testPublishedVersion = version;
        writeJson(REVIEW_KEY, review);
        renderReview();
        loadPublished();
        setStatus("Test Version " + version + " published inside this dashboard · Production unchanged");
      } catch (error) {
        [[PUBLISHED_KEY, before.published], [HISTORY_KEY, before.history], [REVIEW_KEY, before.review]].forEach(([key, value]) => {
          try { if (value === null) localStorage.removeItem(key); else localStorage.setItem(key, value); } catch (_) {}
        });
        setStatus("Test Publish failed: " + (error?.message || String(error)));
        window.alert("Could not save the Test Version in this browser. The previous sandbox state was restored. Check available storage and try again.");
      }
    };
    $("wpSandboxApprove")?.addEventListener("click", approve);
    $("wpSandboxPublish")?.addEventListener("click", publishTest);
    $("wpSandboxViewDraft")?.addEventListener("click", () => { reviewFrame.hidden = false; reviewFrame.srcdoc = renderDocument(review.document); reviewFrame.scrollIntoView({behavior:"smooth",block:"center"}); });
    $("wpSandboxRefresh")?.addEventListener("click", () => { renderReview(); loadPublished(); setStatus("Sandbox refreshed from this browser's saved test data"); });
    viewButtons.forEach((button) => button.addEventListener("click", () => setView(button.dataset.sandboxView)));
    setView("desktop");
    renderReview();
    loadPublished();
    if (new URLSearchParams(location.search).has("wp_review") && review && validDoc(review.document)) {
      reviewPanel.hidden = false;
      reviewFrame.scrollIntoView({behavior:"smooth",block:"center"});
    }
  };
  const waitForAdmin = () => {
    const ready = window.WPAuthReady;
    if (!ready || typeof ready.then !== "function") return;
    ready.then((authorized) => { if (authorized) init(); }).catch(() => {});
  };
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", waitForAdmin, { once: true });
  else waitForAdmin();
})();

admin/wordpress-templates.css:
/* Grocery template suite — isolated preview surfaces */
.hf-wp-templates-page{max-width:1500px;margin:0 auto;padding:clamp(16px,2.5vw,30px)}
.hf-wpt-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:18px}
.hf-wpt-heading h1{margin:5px 0 7px;font-size:clamp(25px,3vw,34px);letter-spacing:-.04em;color:#2b2a3d}
.hf-wpt-heading p:not(.page-eyebrow){margin:0;color:#73798a;max-width:700px;line-height:1.6}
.hf-wpt-architecture{display:flex;align-items:center;gap:13px;padding:13px 16px;border:1px solid #e4ded3;border-radius:13px;background:#fffdf8;color:#54483c;margin:18px 0}
.hf-wpt-architecture-mark{display:grid;place-items:center;flex:0 0 38px;height:38px;border-radius:11px;background:#2b2a3d;color:#f2d9ae;font-size:12px;font-weight:900;letter-spacing:.08em}
.hf-wpt-architecture>div:nth-child(2){min-width:0;flex:1}
.hf-wpt-architecture strong{display:block;font-size:12px;color:#493e32}
.hf-wpt-architecture p{margin:4px 0 0;font-size:10px;line-height:1.55;color:#746b60}
.hf-wpt-connection{flex:0 0 auto;padding:6px 9px;border:1px solid #e7dfd3;border-radius:99px;color:#92754e;font-size:8px;font-weight:800;letter-spacing:.1em}
.hf-wpt-template-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:20px 0 11px}
.hf-wpt-eyebrow{display:block;font-size:8px;font-weight:850;letter-spacing:.14em;color:#99939a}
.hf-wpt-template-bar-copy strong{display:block;margin-top:4px;color:#343342;font-size:14px}
.hf-wpt-template-tabs{display:flex;gap:6px;flex-wrap:wrap}
.hf-wpt-template-tabs button{display:flex;align-items:center;gap:9px;min-height:46px;padding:7px 12px;border:1px solid #e4e3df;border-radius:10px;background:#fff;color:#555768;text-align:left;cursor:pointer}
.hf-wpt-template-tabs button.is-active{border-color:#c97b3d;background:#fffaf4;box-shadow:0 0 0 2px rgba(201,123,61,.1)}
.hf-wpt-tab-number{color:#b27b4d;font-size:9px;font-weight:900}
.hf-wpt-template-tabs strong,.hf-wpt-template-tabs small{display:block}
.hf-wpt-template-tabs strong{font-size:10px}.hf-wpt-template-tabs small{margin-top:2px;color:#92909a;font-size:8px}
.hf-wpt-preview-shell{overflow:hidden;border:1px solid #e2e3e6;border-radius:15px;background:#fff;box-shadow:0 10px 28px rgba(35,40,52,.055)}
.hf-wpt-preview-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 15px;border-bottom:1px solid #e9e9eb;background:#fff}
.hf-wpt-preview-meta{display:flex;align-items:center;gap:10px;min-width:0}
.hf-wpt-live-dot{width:8px;height:8px;flex:0 0 8px;border-radius:50%;background:#6e9a76;box-shadow:0 0 0 4px #edf5ed}
.hf-wpt-preview-meta strong,.hf-wpt-preview-meta small{display:block}
.hf-wpt-preview-meta strong{color:#333342;font-size:12px}.hf-wpt-preview-meta small{margin-top:3px;color:#888b96;font-size:9px}
.hf-wpt-preview-actions{display:flex;align-items:center;gap:9px}
.hf-wpt-device-toggle{display:flex;gap:3px;padding:3px;border:1px solid #e5e6e9;border-radius:8px;background:#f5f6f8}
.hf-wpt-device-toggle button{min-height:28px;padding:5px 9px;border:0;border-radius:6px;background:transparent;color:#7e8491;font-size:9px;font-weight:750;cursor:pointer}
.hf-wpt-device-toggle button.is-active{background:#fff;color:#35486d;box-shadow:0 1px 4px rgba(20,30,45,.1)}
.hf-wpt-use-button{display:inline-flex;align-items:center;justify-content:center;min-height:34px;padding:8px 13px;border:1px solid #34466d;border-radius:8px;background:#34466d;color:#fff;text-decoration:none;font-size:10px;font-weight:750;white-space:nowrap}
.hf-wpt-browserbar{display:flex;align-items:center;gap:9px;height:31px;padding:0 12px;border-bottom:1px solid #e7e8eb;background:#f7f8fa;color:#89909c}
.hf-wpt-browser-dots{display:flex;gap:4px}.hf-wpt-browser-dots i{width:6px;height:6px;border-radius:50%;background:#d2d4d9}
.hf-wpt-lock{font-size:9px}.hf-wpt-browser-address{flex:1;overflow:hidden;padding:4px 9px;border:1px solid #e8e9ec;border-radius:5px;background:#fff;font-size:8px;white-space:nowrap;text-overflow:ellipsis}
.hf-wpt-browser-label{font-size:8px;font-weight:850;letter-spacing:.12em;color:#71829a}
.hf-wpt-viewport{display:flex;justify-content:center;min-height:690px;padding:0;background:#e9edf1;overflow:auto}
.hf-wpt-viewport.is-mobile{padding:22px 12px}
.hf-wpt-viewport.is-mobile .hf-storefront{width:390px;min-width:390px;max-width:390px;min-height:760px;border:7px solid #28303c;border-radius:25px;overflow:hidden;box-shadow:0 12px 34px rgba(20,25,35,.2)}
.hf-storefront{--shop-accent:#b94f35;--shop-ink:#273b32;--shop-paper:#fbf8f1;--shop-soft:#f4eadb;width:100%;min-width:0;max-width:1400px;min-height:690px;background:var(--shop-paper);color:var(--shop-ink);font-family:"DM Sans",Inter,system-ui,sans-serif}
.hf-storefront[data-template="fresh-produce"]{--shop-accent:#657c4a;--shop-ink:#293c31;--shop-paper:#f7f7ef;--shop-soft:#e9eddf}
.hf-storefront[data-template="express-grocery"]{--shop-accent:#df6b35;--shop-ink:#27354a;--shop-paper:#f7f8fb;--shop-soft:#fff0e7}
.hf-storefront[data-template="wholesale-bulk"]{--shop-accent:#344b70;--shop-ink:#25344b;--shop-paper:#f5f7fa;--shop-soft:#e9eef5}
.hf-storefront button{font:inherit;cursor:pointer}
.hf-storefront img{display:block;max-width:100%;object-fit:cover}
.hf-storefront button:focus-visible,.hf-storefront input:focus-visible{outline:2px solid var(--shop-accent);outline-offset:2px}
.hf-shop-topline,.hf-fresh-top,.hf-express-ribbon,.hf-b2b-strip{display:flex;justify-content:space-between;gap:12px;padding:8px 5%;background:var(--shop-ink);color:#fff;font-size:9px;letter-spacing:.03em}
.hf-shop-topline span,.hf-fresh-top span,.hf-b2b-strip span{opacity:.75}
.hf-shop-header,.hf-fresh-header,.hf-express-header,.hf-b2b-header{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:17px 5%;background:#fff}
.hf-shop-logo{font-size:23px;font-weight:900;letter-spacing:-1.2px;color:var(--shop-ink)}.hf-shop-logo>span:first-child{color:var(--shop-accent);font-size:15px}.hf-shop-logo>span:last-child{color:var(--shop-accent)}
.hf-shop-search{display:flex;align-items:center;gap:9px;width:min(43%,470px);height:39px;padding:0 12px;border:1px solid #e3e5e6;border-radius:8px;background:#fafafa;color:#8b929b}
.hf-shop-search input,.hf-express-search input{width:100%;border:0;outline:0;background:transparent;color:#333;font:10px "DM Sans",sans-serif}
.hf-shop-header-links{display:flex;align-items:center;gap:15px;font-size:10px}
.hf-shop-cart,.hf-fresh-bag,.hf-express-cart,.hf-b2b-account{padding:10px 13px;border:0;border-radius:7px;background:var(--shop-ink);color:#fff;font-size:10px;font-weight:750}
.hf-shop-cart b,.hf-fresh-bag b,.hf-express-cart b{display:inline-grid;place-items:center;min-width:18px;height:18px;margin-left:6px;border-radius:50%;background:var(--shop-accent);color:#fff}
.hf-shop-nav{display:flex;justify-content:center;gap:26px;padding:12px 5%;border-top:1px solid #f0f0ed;border-bottom:1px solid #e8e8e2;background:#fff}
.hf-shop-nav button,.hf-fresh-cats button,.hf-express-cats button{padding:4px 0;border:0;background:none;color:#68736d;font-size:9px}
.hf-shop-nav button.is-active{color:var(--shop-accent);font-weight:850}
.hf-shop-hero{display:grid;grid-template-columns:1fr 1fr;min-height:290px;background:var(--shop-soft)}
.hf-shop-hero>div{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding:42px 9% 42px 12%}
.hf-shop-kicker,.hf-fresh-hero-copy small,.hf-express-hero small,.hf-b2b-hero small{font-size:8px;font-weight:850;letter-spacing:.16em;color:var(--shop-accent)}
.hf-shop-hero h2,.hf-fresh-hero h2,.hf-express-hero h2,.hf-b2b-hero h2{margin:12px 0;font-family:"Playfair Display",Georgia,serif;font-size:clamp(27px,3.5vw,48px);line-height:1.08;letter-spacing:-.035em;color:var(--shop-ink)}
.hf-shop-hero p,.hf-fresh-hero p,.hf-express-hero p,.hf-b2b-hero p{max-width:430px;color:#6c766f;font-size:11px;line-height:1.8}
.hf-shop-hero-cta,.hf-fresh-hero-copy button,.hf-express-hero button,.hf-b2b-hero button{margin-top:13px;padding:12px 16px;border:0;border-radius:6px;background:var(--shop-accent);color:#fff;font-size:10px;font-weight:800}
.hf-shop-hero>img{width:100%;height:100%;min-height:290px}
.hf-shop-trust{display:flex;gap:14px;flex-wrap:wrap;margin-top:20px;color:#69766b;font-size:8px}
.hf-shop-promo-row{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#e6e4dc}
.hf-shop-promo-row>div{display:flex;flex-direction:column;gap:5px;padding:18px 22px;background:#fff}
.hf-shop-promo-row small,.hf-shop-section-heading small,.hf-fresh-section-title small,.hf-express-title small,.hf-b2b-buying small,.hf-b2b-table-head small{color:var(--shop-accent);font-size:7px;font-weight:900;letter-spacing:.15em}
.hf-shop-promo-row strong{font-family:"Playfair Display",Georgia,serif;font-size:14px}.hf-shop-promo-row span{color:#8a8d87;font-size:8px}
.hf-shop-products,.hf-fresh-products,.hf-express-products,.hf-b2b-products{padding:30px 5% 42px}
.hf-shop-section-heading,.hf-express-title,.hf-b2b-table-head{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-bottom:18px}
.hf-shop-section-heading h3,.hf-fresh-section-title h3,.hf-express-title h3,.hf-b2b-buying h3,.hf-b2b-table-head h3{margin:5px 0 0;font-family:"Playfair Display",Georgia,serif;font-size:23px;color:var(--shop-ink)}
.hf-shop-section-heading>span,.hf-express-title>span{color:#92968f;font-size:8px}
.hf-shop-product-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}
.hf-shop-product{min-width:0;border:1px solid #e9e7e0;border-radius:8px;background:#fff;overflow:hidden}
.hf-shop-product[hidden],.hf-fresh-card[hidden],.hf-express-card[hidden],.hf-b2b-products tr[hidden]{display:none}
.hf-shop-product-image{position:relative;height:135px;background:#f2f1eb}
.hf-shop-product-image img{width:100%;height:100%}
.hf-shop-product-tag{position:absolute;top:8px;left:8px;padding:4px 5px;border-radius:3px;background:#fff;color:var(--shop-accent);font-size:6px;font-weight:900;letter-spacing:.08em}
.hf-shop-add{position:absolute;right:8px;bottom:8px;width:27px;height:27px;border:0;border-radius:50%;background:var(--shop-accent);color:#fff;font-size:17px}
.hf-shop-product-info{padding:10px}
.hf-shop-product-info>small,.hf-shop-product-info>strong{display:block}
.hf-shop-product-info>small{color:#969990;font-size:7px}
.hf-shop-product-info>strong{min-height:28px;margin:4px 0 8px;color:#39443c;font-size:9px}
